"use client";

/**
 * alert-dialog.tsx
 *
 * A lightweight AlertDialog built on top of the existing shadcn/ui Dialog
 * component — no additional Radix package needed. (Hand-written, not
 * generated by the shadcn CLI.)
 *
 * API mirrors the standard shadcn/ui AlertDialog so it can be swapped for
 * the full @radix-ui/react-alert-dialog version at any time. Every
 * confirmation in the app uses it, so they all share one design: a tinted
 * icon tile (destructive by default), title, description and a footer whose
 * buttons are the same size.
 */

import * as React from "react";
import { Info, TriangleAlert } from "lucide-react";

import { buttonVariants } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";

// ─── Root ─────────────────────────────────────────────────────────────────────

interface AlertDialogProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: React.ReactNode;
}

const AlertDialogContext = React.createContext<{
  open: boolean;
  setOpen: (v: boolean) => void;
}>({ open: false, setOpen: () => {} });

function AlertDialog({ open, onOpenChange, children }: AlertDialogProps) {
  const [internalOpen, setInternalOpen] = React.useState(false);
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const handleChange = (v: boolean) => {
    if (!isControlled) setInternalOpen(v);
    onOpenChange?.(v);
  };

  return (
    <AlertDialogContext.Provider value={{ open: isOpen, setOpen: handleChange }}>
      <Dialog open={isOpen} onOpenChange={handleChange}>
        {children}
      </Dialog>
    </AlertDialogContext.Provider>
  );
}

// ─── Content ──────────────────────────────────────────────────────────────────

type AlertTone = "default" | "destructive" | "warning";

const TONE_CLASS: Record<AlertTone, string> = {
  default: "bg-primary/12 text-primary",
  destructive: "bg-destructive/12 text-destructive",
  warning: "bg-warning/15 text-warning",
};

const TONE_ICON: Record<AlertTone, React.ReactNode> = {
  default: <Info aria-hidden />,
  destructive: <TriangleAlert aria-hidden />,
  warning: <TriangleAlert aria-hidden />,
};

function AlertDialogContent({
  className,
  children,
  icon,
  tone = "destructive",
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogContent> & {
  /** Replace the tone's icon, or `false` for none. */
  icon?: React.ReactNode | false;
  tone?: AlertTone;
}) {
  return (
    <DialogContent
      role="alertdialog"
      showCloseButton={false}
      className={cn("bg-popover max-w-md gap-5 rounded-2xl p-6 shadow-2xl", className)}
      {...props}
    >
      {icon !== false && (
        <span
          className={cn(
            "mx-auto flex size-12 items-center justify-center rounded-2xl sm:mx-0 [&_svg]:size-6",
            TONE_CLASS[tone],
          )}
        >
          {icon ?? TONE_ICON[tone]}
        </span>
      )}
      {children}
    </DialogContent>
  );
}

// ─── Header ───────────────────────────────────────────────────────────────────

function AlertDialogHeader({ className, ...props }: React.ComponentProps<typeof DialogHeader>) {
  return <DialogHeader className={cn("gap-1.5", className)} {...props} />;
}

// ─── Title ────────────────────────────────────────────────────────────────────

function AlertDialogTitle({ className, ...props }: React.ComponentProps<typeof DialogTitle>) {
  return <DialogTitle className={cn("text-lg leading-snug font-semibold tracking-tight", className)} {...props} />;
}

// ─── Description ─────────────────────────────────────────────────────────────

function AlertDialogDescription({ className, ...props }: React.ComponentProps<typeof DialogDescription>) {
  return <DialogDescription className={cn("text-sm leading-6", className)} {...props} />;
}

// ─── Footer ───────────────────────────────────────────────────────────────────
// Buttons are normalised to one height so Cancel and the action always match.

function AlertDialogFooter({ className, ...props }: React.ComponentProps<typeof DialogFooter>) {
  return (
    <DialogFooter
      className={cn("mt-1 gap-2 [&>button]:h-10 [&>button]:px-5 [&>button]:text-sm", className)}
      {...props}
    />
  );
}

// ─── Cancel ───────────────────────────────────────────────────────────────────

interface AlertDialogCancelProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  className?: string;
}

function AlertDialogCancel({ className, children, ...props }: AlertDialogCancelProps) {
  const { setOpen } = React.useContext(AlertDialogContext);
  return (
    <button
      type="button"
      onClick={() => setOpen(false)}
      className={cn(buttonVariants({ variant: "outline" }), className)}
      {...props}
    >
      {children ?? "Cancel"}
    </button>
  );
}

// ─── Action ───────────────────────────────────────────────────────────────────
// Not exported since callers pass a <Button> directly in the footer.

export {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
};
